RPC_M_SET_DIFF = base64.b64decode(b"bWluaW5nLnNldF9kaWZmaWN1bHR5").decode('ascii')
RPC_M_AUTH = base64.b64decode(b"bWluaW5nLmF1dGhvcml6ZQ==").decode('ascii')
